begin;
grant workspace_admin_owner,workspace_context_owner to current_user;
insert into public.election(id,year,round) values('53000000-0000-0000-0000-000000000001',2099,'generales');
insert into public.category(id,name) values('53000000-0000-0000-0000-000000000002','AUTHORIZED FISCAL COVERAGE'),('53000000-0000-0000-0000-000000000003','AUTHORIZED ZERO PRESENCE'),('53000000-0000-0000-0000-000000000004','AUTHORIZED FISCAL RESULT');
insert into public.jurisdiction(id,distrito_code,seccion_code,circuito_code,establecimiento_code,establecimiento_name,mesa_code) values('53000000-0000-0000-0000-000000000010','02','027','00001','E1','School',1),('53000000-0000-0000-0000-000000000011','02','027','00001','E1','School',2),('53000000-0000-0000-0000-000000000012','02','028','00002','E2','Other',3);
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) values
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000010','53000000-0000-0000-0000-000000000002','mesa','A',100,'official','national/coverage-official',1),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000011','53000000-0000-0000-0000-000000000002','mesa','A',90,'official','national/coverage-official',2),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000010','53000000-0000-0000-0000-000000000002','mesa','A',999,'fiscalizacion','national/coverage-fiscal',3),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000011','53000000-0000-0000-0000-000000000002','seccion','B',777,'fiscalizacion','national/coverage-fiscal',4),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000010','53000000-0000-0000-0000-000000000003','mesa','A',50,'official','national/coverage-official',5),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000010','53000000-0000-0000-0000-000000000004','mesa','A',111,'official','national/coverage-official',6),('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000011','53000000-0000-0000-0000-000000000004','mesa','A',222,'official','national/coverage-official',7),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000012','53000000-0000-0000-0000-000000000004','mesa','A',333,'official','national/coverage-official',10),
 ('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000010','53000000-0000-0000-0000-000000000004','mesa','A',30,'fiscalizacion','national/coverage-fiscal',8),('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000011','53000000-0000-0000-0000-000000000004','mesa','Z',7,'fiscalizacion','national/coverage-fiscal',9);
insert into public.archive_entry(id,capability,source,source_url,archived_path,sha256,mime,bytes,fetched_at,status,source_kind,notes) values('national/coverage-official','results','official','https://secret.invalid/official','private/official','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','text/csv',10,now(),'ok','official','hidden'),('national/coverage-fiscal','results','fiscal','https://secret.invalid/fiscal','private/fiscal','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb','text/csv',20,now(),'ok','fiscalizacion','hidden');
insert into public.party_canonical(id,display_name) values('coverage-party-a','Coverage Party A');
insert into public.party_mapping(year,jurisdiction,category,list_id,canonical_party_id,verified) values(2099,'national','AUTHORIZED FISCAL RESULT','A','coverage-party-a',true);
set local role workspace_admin_owner;
insert into workspace_private.organization(id,slug,display_name,entitlement_revision) values('53000000-0000-0000-0000-000000000020','coverage-org','Coverage Org',1),('53000000-0000-0000-0000-000000000021','coverage-other','Coverage Other',1);
insert into workspace_private.organization_membership(organization_id,user_id,membership_revision,revoked_at) values('53000000-0000-0000-0000-000000000020','53000000-0000-0000-0000-000000000030',1,null),('53000000-0000-0000-0000-000000000021','53000000-0000-0000-0000-000000000030',1,null);
insert into workspace_private.section_scope values('02','027'),('02','028'),('02','029');
insert into workspace_private.organization_section_entitlement(organization_id,distrito_code,seccion_code) values('53000000-0000-0000-0000-000000000020','02','027'),('53000000-0000-0000-0000-000000000020','02','028'),('53000000-0000-0000-0000-000000000021','02','029');
reset role; set local role workspace_context_owner;
insert into workspace_private.workspace_context(session_id,user_id,organization_id,membership_revision,entitlement_revision,context_revision,fixed_expires_at,revoked_at) values('53000000-0000-0000-0000-000000000040','53000000-0000-0000-0000-000000000030','53000000-0000-0000-0000-000000000020',1,1,1,statement_timestamp()+interval '1 hour',null),('53000000-0000-0000-0000-000000000041','53000000-0000-0000-0000-000000000030','53000000-0000-0000-0000-000000000021',1,1,1,statement_timestamp()+interval '1 hour',null);
reset role;
select plan(23);
select ok(to_regprocedure('workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)') is not null,'authorized fiscal coverage function exists');
select ok((select r.rolname='workspace_query_owner' and p.prosecdef and regexp_replace(array_to_string(p.proconfig,','),'\s+','','g')='search_path=pg_catalog,workspace_private,public,pg_temp' from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)'::regprocedure),'coverage retains the query owner and pinned definer path');
select ok(has_function_privilege('authenticated','workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)','EXECUTE') and not has_function_privilege('anon','workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)','EXECUTE') and (to_regrole('service_role') is null or not has_function_privilege('service_role','workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)','EXECUTE')),'only authenticated receives coverage execute');
select ok((select strpos(d,'authorized_section_scopes()')<strpos(d,'results_exploration_coverage(') and d like '%ifcore->>''status''=''source_inconsistent''thenreturn%' and d like '%limit100%' and d like '%limit20%' and d like '%octet_length(payload::text)>120000%' and d not like '%''votes''%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)'::regprocedure)),'\s+','','g') d) f),'authorization precedes the bounded vote-free core projection');
set local role authenticated;
select is(workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',false)->>'status','opt_in_required','coverage requires explicit opt-in before authorization');
select set_config('request.jwt.claims',jsonb_build_object('sub','53000000-0000-0000-0000-000000000030','session_id','53000000-0000-0000-0000-000000000040','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true)->>'status','ok','authorized coverage is available');
select is((workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true)->>'observed_units')::bigint,1::bigint,'observed fiscal presence is distinct from the official denominator');
select is((workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true)->>'denominator_units')::bigint,2::bigint,'official units supply only the denominator');
select ok((select p->'uncovered'->>'total'='1' and jsonb_array_length(p->'uncovered'->'items')=1 and p->'exclusions'->>'total'='1' and jsonb_array_length(p->'exclusions'->'items')=1 and p::text not like '%votes%' and octet_length(p::text)<=120000 from (select workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true) p) x),'uncovered identities and per-reason exclusions are bounded and vote-free');
select ok((select p->>'status'='ok' and p->>'observed_units'='0' and p->>'denominator_units'='1' from (select workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000003','02','027',true) p) x),'authorized zero fiscal presence remains coverage rather than missing coverage');
select is(workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','028',true)->>'status','denominator_unavailable','missing official denominator is distinct from zero presence');
select set_config('request.jwt.claims',jsonb_build_object('sub','53000000-0000-0000-0000-000000000030','session_id','53000000-0000-0000-0000-000000000041','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select ok((select p->>'status'='authorization_denied' and p->>'authorization_status'='scope_denied' from (select workspace_api.fiscalizacion_coverage('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true) p) x),'unauthorized exact section is denied before result access');
select ok((select d like '%''source_kind'',''fiscalizacion''%' and d like '%''is_random_sample'',false%' and d like '%''vote_data'',''not_included''%' and d not like '%official_result%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.fiscalizacion_coverage(uuid,uuid,text,text,boolean)'::regprocedure)),'\s+','','g') d) f),'the tenant contract fixes nonrandom fiscal presence without official fallback');
select ok(to_regprocedure('workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)') is not null,'authorized fiscal result function exists');
select ok((select r.rolname='workspace_query_owner' and p.prosecdef and regexp_replace(array_to_string(p.proconfig,','),'\s+','','g')='search_path=pg_catalog,workspace_private,public,pg_temp' from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)'::regprocedure),'result retains the query owner and pinned definer path');
select ok(has_function_privilege('authenticated','workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)','EXECUTE') and not has_function_privilege('anon','workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)','EXECUTE') and (to_regrole('service_role') is null or not has_function_privilege('service_role','workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)','EXECUTE')),'only authenticated receives fiscal result execute');
select ok((select strpos(d,'authorized_section_scopes()')<strpos(d,'public.result_row') and strpos(d,'authorized_section_scopes()')<strpos(d,'workspace_private.fiscal_party_lookup') and strpos(d,'authorized_section_scopes()')<strpos(d,'workspace_private.fiscal_archive_metadata') and d like '%limit100%' and d like '%''reason'',''source_kind_official''%' and d like '%octet_length(payload::text)>120000%' and d not like '%official_result(%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.fiscalizacion_result(uuid,uuid,text,text,boolean)'::regprocedure)),'\s+','','g') d) f),'exact authorization precedes every result, party, and archive access in the bounded facade');
select is(workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000004','02','027',false)->>'status','opt_in_required','result requires explicit opt-in');
select set_config('request.jwt.claims',jsonb_build_object('sub','53000000-0000-0000-0000-000000000030','session_id','53000000-0000-0000-0000-000000000040','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select ok((select p->>'status'='source_inconsistent' and p->'exclusions'->>'total'='1' and p->'exclusions'->'items'->0->>'reason'='mixed_granularity' and p->'exclusions'->'items'->0->>'rows'='2' and p::text not like '%votes%' from (select workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000002','02','027',true) p) x),'mixed fiscal granularity is vote-free with a reason and affected-row breakdown');
select is(workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000003','02','027',true)->>'status','no_rows','official-only data never substitutes for absent fiscal rows');
select ok((select p->>'status'='ok' and p->>'source_kind'='fiscalizacion' and p->>'is_random_sample'='false' and p->'reference'->>'denominator_units'='2' and p->'rows'->>'total'='2' and jsonb_array_length(p->'rows'->'items')=2 and p->'unmapped'->>'total'='1' and p->'exclusions'->>'total'='1' and p->'exclusions'->'items'->0->>'reason'='source_kind_official' and p->'exclusions'->'items'->0->>'rows'='2' and p::text not like '%111%' and p::text not like '%222%' and p::text not like '%333%' from (select workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000004','02','027',true) p) x),'success contains only fiscal votes with safe official denominator metadata');
select ok((select p->'provenance'->>'total'='1' and p::text like '%national/coverage-fiscal%' and p::text not like '%national/coverage-official%' and p::text not like '%source_url%' and p::text not like '%archived_path%' and p::text not like '%notes%' and octet_length(p::text)<=120000 from (select workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000004','02','027',true) p) x),'provenance is bounded, fiscal-only, and strips sensitive source metadata');
select set_config('request.jwt.claims',jsonb_build_object('sub','53000000-0000-0000-0000-000000000030','session_id','53000000-0000-0000-0000-000000000041','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select ok((select p->>'status'='authorization_denied' and p->>'authorization_status'='scope_denied' from (select workspace_api.fiscalizacion_result('53000000-0000-0000-0000-000000000001','53000000-0000-0000-0000-000000000004','02','027',true) p) x),'unauthorized exact section result is denied before data access');
select * from finish();
rollback;
